// Supabase Edge Function "lifeops-api": the LifeOps server code for the GitHub Pages build.
// See PAGES_DEPLOYMENT.md. server.mjs is generated by `npm run build:pages` (not in git).
import process from "node:process";
import { Buffer } from "node:buffer";
import { createHandler, normalizeAppBase, parseAllowedOrigins, type FetchApp } from "./handler.ts";

const FUNCTION_NAME = "lifeops-api";

function env(name: string): string | undefined {
  const value = Deno.env.get(name);
  return value && value.trim() ? value : undefined;
}

/** Supabase injects SUPABASE_PUBLISHABLE_KEYS / SUPABASE_SECRET_KEYS as JSON objects of named keys. */
function keyFromDictionary(name: string): string | undefined {
  const raw = env(name);
  if (!raw) return undefined;
  try {
    const keys = JSON.parse(raw) as Record<string, unknown>;
    const value = keys.default ?? Object.values(keys)[0];
    return typeof value === "string" && value ? value : undefined;
  } catch {
    return undefined;
  }
}

// The server code reads SUPABASE_PUBLISHABLE_KEY and SUPABASE_SECRET_KEY. Secret names starting with
// SUPABASE_ are reserved on Supabase, so these two are derived from what the platform injects.
const derived: Record<string, string | undefined> = {
  SUPABASE_PUBLISHABLE_KEY: env("SUPABASE_PUBLISHABLE_KEY") ?? keyFromDictionary("SUPABASE_PUBLISHABLE_KEYS") ?? env("SUPABASE_ANON_KEY"),
  SUPABASE_SECRET_KEY: env("SUPABASE_SECRET_KEY") ?? keyFromDictionary("SUPABASE_SECRET_KEYS") ?? env("SUPABASE_SERVICE_ROLE_KEY"),
  NODE_ENV: env("NODE_ENV") ?? "production",
};
for (const [name, value] of Object.entries(derived)) {
  if (value && process.env[name] !== value) process.env[name] = value;
}
// The bundled server code reads the global process and Buffer; Buffer is not a global for local
// modules in Deno, and process is set as well in case the runtime does not provide it.
(globalThis as { process?: unknown }).process ??= process;
(globalThis as { Buffer?: unknown }).Buffer ??= Buffer;

// Loaded on the first request, after the environment is set up; a literal path so the deploy
// bundler includes it. Deno keeps a failed import failed, so a broken bundle answers 500 until
// Supabase starts a new worker (the error is in the function's logs).
let app: Promise<FetchApp> | undefined;
function loadApp(): Promise<FetchApp> {
  app ??= import("./server.mjs").then((module) => (module.default ?? module) as FetchApp);
  return app;
}

Deno.serve(
  createHandler({
    functionName: FUNCTION_NAME,
    appBase: normalizeAppBase(env("LIFEOPS_APP_BASE") ?? "lifeops-ai"),
    allowedOrigins: parseAllowedOrigins(env("LIFEOPS_ALLOWED_ORIGINS") ?? "https://gopalinternship-unibasel.github.io"),
    loadApp,
  }),
);
